import{_ as l,o as i,c as e,ag as r}from"./chunks/framework.OsDJF_Ea.js";const p=JSON.parse('{"title":"파일","description":"","frontmatter":{},"headers":[],"relativePath":"02-user-guide/files.md","filePath":"02-user-guide/files.md","lastUpdated":1776160579000}'),t={name:"02-user-guide/files.md"};function o(s,a,n,h,d,c){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="파일" tabindex="-1">파일 <a class="header-anchor" href="#파일" aria-label="Permalink to &quot;파일&quot;">​</a></h1><p>메시지에 파일을 첨부하고 관리합니다.</p><h2 id="파일-업로드" tabindex="-1">파일 업로드 <a class="header-anchor" href="#파일-업로드" aria-label="Permalink to &quot;파일 업로드&quot;">​</a></h2><ol><li>메시지 입력창의 <strong>파일 첨부</strong> 아이콘을 클릭합니다.</li><li>업로드할 파일을 선택합니다.</li><li>파일이 메시지와 함께 전송됩니다.</li></ol><h3 id="드래그-앤-드롭" tabindex="-1">드래그 앤 드롭 <a class="header-anchor" href="#드래그-앤-드롭" aria-label="Permalink to &quot;드래그 앤 드롭&quot;">​</a></h3><p>메시지 입력 영역에 파일을 직접 드래그하여 업로드할 수도 있습니다.</p><h2 id="채널-파일-저장소" tabindex="-1">채널 파일 저장소 <a class="header-anchor" href="#채널-파일-저장소" aria-label="Permalink to &quot;채널 파일 저장소&quot;">​</a></h2><p>채널의 모든 파일을 웹하드처럼 편리하게 관리할 수 있습니다.</p><h3 id="파일-탭-열기" tabindex="-1">파일 탭 열기 <a class="header-anchor" href="#파일-탭-열기" aria-label="Permalink to &quot;파일 탭 열기&quot;">​</a></h3><ol><li>채널에서 오른쪽 패널의 <strong>파일</strong> 탭을 클릭합니다.</li><li>채널에 업로드된 모든 파일이 목록으로 표시됩니다.</li></ol><h3 id="파일-검색" tabindex="-1">파일 검색 <a class="header-anchor" href="#파일-검색" aria-label="Permalink to &quot;파일 검색&quot;">​</a></h3><p>파일명 검색으로 원하는 파일을 빠르게 찾을 수 있습니다.</p><ol><li>검색 입력창에 파일명을 입력합니다.</li><li>실시간으로 검색 결과가 필터링됩니다.</li></ol><h3 id="파일-유형-필터" tabindex="-1">파일 유형 필터 <a class="header-anchor" href="#파일-유형-필터" aria-label="Permalink to &quot;파일 유형 필터&quot;">​</a></h3><p>유형별로 파일을 필터링할 수 있습니다.</p><ul><li><strong>전체</strong>: 모든 파일</li><li><strong>이미지</strong>: JPG, PNG, GIF, SVG 등</li><li><strong>문서</strong>: PDF, DOC, DOCX, XLS, XLSX, PPT, PPTX, TXT 등</li><li><strong>미디어</strong>: MP3, MP4, WAV 등</li><li><strong>압축</strong>: ZIP, RAR, TAR 등</li></ul><h3 id="파일-정렬" tabindex="-1">파일 정렬 <a class="header-anchor" href="#파일-정렬" aria-label="Permalink to &quot;파일 정렬&quot;">​</a></h3><p>컬럼 헤더를 클릭하여 정렬할 수 있습니다.</p><ul><li><strong>파일</strong>: 파일명순 정렬</li><li><strong>크기</strong>: 파일 크기순 정렬</li><li><strong>등록일</strong>: 업로드 날짜순 정렬</li></ul><p>오름차순/내림차순은 헤더 클릭 시 토글됩니다.</p><h2 id="파일-다운로드" tabindex="-1">파일 다운로드 <a class="header-anchor" href="#파일-다운로드" aria-label="Permalink to &quot;파일 다운로드&quot;">​</a></h2><h3 id="개별-다운로드" tabindex="-1">개별 다운로드 <a class="header-anchor" href="#개별-다운로드" aria-label="Permalink to &quot;개별 다운로드&quot;">​</a></h3><p>메시지에 첨부된 파일을 클릭하면 다운로드됩니다. 파일 목록에서 다운로드 아이콘을 클릭해도 됩니다.</p><h3 id="일괄-다운로드" tabindex="-1">일괄 다운로드 <a class="header-anchor" href="#일괄-다운로드" aria-label="Permalink to &quot;일괄 다운로드&quot;">​</a></h3><p>여러 파일을 한 번에 다운로드할 수 있습니다.</p><ol><li>다운로드할 파일의 체크박스를 선택합니다.</li><li>하단에 선택된 파일 개수가 표시됩니다.</li><li><strong>선택 다운로드</strong> 버튼을 클릭합니다.</li><li>선택한 파일들이 ZIP 압축파일로 다운로드됩니다.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>최대 20개 파일까지 일괄 다운로드 가능합니다.</p></div><h2 id="원본-메시지로-이동" tabindex="-1">원본 메시지로 이동 <a class="header-anchor" href="#원본-메시지로-이동" aria-label="Permalink to &quot;원본 메시지로 이동&quot;">​</a></h2><p>파일 목록에서 파일이 첨부된 원본 메시지로 바로 이동할 수 있습니다.</p><ol><li>파일 행의 메시지 아이콘을 클릭합니다.</li><li>채널 메시지 목록으로 스크롤 이동합니다.</li><li>해당 메시지가 노란색으로 하이라이트됩니다.</li></ol><h2 id="지원-파일-형식" tabindex="-1">지원 파일 형식 <a class="header-anchor" href="#지원-파일-형식" aria-label="Permalink to &quot;지원 파일 형식&quot;">​</a></h2><ul><li>이미지: JPG, PNG, GIF, SVG</li><li>문서: PDF, DOC, DOCX, XLS, XLSX, PPT, PPTX</li><li>기타: ZIP, TXT, CSV</li></ul><h2 id="파일-미리보기" tabindex="-1">파일 미리보기 <a class="header-anchor" href="#파일-미리보기" aria-label="Permalink to &quot;파일 미리보기&quot;">​</a></h2><p>이미지 파일은 메시지 내에서 미리보기가 표시됩니다. 클릭하면 원본 크기로 확인할 수 있습니다.</p>',34)])])}const P=l(t,[["render",o]]);export{p as __pageData,P as default};
